INSERT INTO reviews (id, title, release_year, poster, trailer_url, content, author_id, created_at) VALUES
  (1, 'Побег из Шоушенка', 1994, 'shawshank.jpg', 'https://www.youtube.com/results?search_query=%D0%9F%D0%BE%D0%B1%D0%B5%D0%B3%20%D0%B8%D0%B7%20%D0%A8%D0%BE%D1%83%D1%88%D0%B5%D0%BD%D0%BA%D0%B0%20%D1%82%D1%80%D0%B5%D0%B9%D0%BB%D0%B5%D1%80', 'Фильм о том, как надежда помогает пережить годы за решёткой.

Тюремная драма без громких эффектов: здесь важны неспешный рассказ, дружба двух заключённых и ощущение времени, которое тянется годами. Тим Роббинс и Морган Фриман играют так, что в каждом взгляде есть история.

Финал одновременно тёплый и неожиданный. Фильм, который не надоедает пересматривать.', 1, '2025-08-05 12:00:00'),
  (2, 'Зеленая миля', 1999, 'green-mile.jpg', 'https://www.youtube.com/watch?v=TODt_q-_4C4', '«Они помогли ему убить себя и так происходит каждый день во всем мире»...

Фильм, который я могу смело назвать шедевром. Фильм, который длится три часа и которые пролетают незаметно. Фильм, который смотрится каждый раз как в первый. Фильм, который нельзя забыть и которым нельзя не проникнуться. Фильм, котрый заставляет задуматься о жизни, которую мы тратим на пустяки, теша себя иллюзией бессмертия, о смерти, которая не щадит никого.

Фильм о зле, которое не всегда наказуемо и о добре, которое подчас бессильно что-либо изменить. И тебе остается лишь смотреть на то, как вершится суд, над тем кто не должен сидеть на скамье подсудимых.

Фильм, который изменил мое мировоззрение и научил по-другому относиться к жизни.', 1, '2025-08-06 12:00:00'),
  (3, 'Список Шиндлера', 1993, 'schindlers-list.jpg', 'https://www.youtube.com/results?search_query=%D0%A1%D0%BF%D0%B8%D1%81%D0%BE%D0%BA%20%D0%A8%D0%B8%D0%BD%D0%B4%D0%BB%D0%B5%D1%80%D0%B0%20%D1%82%D1%80%D0%B5%D0%B9%D0%BB%D0%B5%D1%80', 'История о том, что даже в самое тёмное время остаётся место человеческому выбору.

Фильм снят в чёрно-белом цвете, и это не стилизация: так история выглядит строже и честнее. Камера почти не отводит взгляд, но и не давит на зрителя, всё держится на актёрах и точных деталях. Лиам Нисон и Рэйф Файнс играют двух людей, которые стоят по разные стороны одного и того же ужаса.

Три часа проходят без ощущения затянутости. После финала хочется помолчать, а не обсуждать. Это тот случай, когда фильм нужно посмотреть хотя бы один раз.', 1, '2025-08-07 12:00:00'),
  (4, 'Форрест Гамп', 1994, 'forrest-gump.jpg', 'https://www.youtube.com/results?search_query=%D0%A4%D0%BE%D1%80%D1%80%D0%B5%D1%81%D1%82%20%D0%93%D0%B0%D0%BC%D0%BF%20%D1%82%D1%80%D0%B5%D0%B9%D0%BB%D0%B5%D1%80', 'Фильм про доброту, верность и умение не сдаваться.

Простой человек проходит через десятилетия американской истории, и каждый эпизод становится маленькой историей про любовь, дружбу и потерю. Том Хэнкс играет так, что Форресту веришь с первой минуты.

Местами фильм наивный, но эта наивность и делает его тёплым. Хорошая картина на вечер, когда хочется доброй истории.', 1, '2025-08-08 12:00:00'),
  (5, 'Властелин колец: Братство Кольца', 2001, 'lotr-fellowship.jpg', 'https://www.youtube.com/results?search_query=%D0%92%D0%BB%D0%B0%D1%81%D1%82%D0%B5%D0%BB%D0%B8%D0%BD%20%D0%BA%D0%BE%D0%BB%D0%B5%D1%86%3A%20%D0%91%D1%80%D0%B0%D1%82%D1%81%D1%82%D0%B2%D0%BE%20%D0%9A%D0%BE%D0%BB%D1%8C%D1%86%D0%B0%20%D1%82%D1%80%D0%B5%D0%B9%D0%BB%D0%B5%D1%80', 'С этого фильма началось путешествие, которое хочется повторить.

Первая часть трилогии знакомит со Средиземьем и собирает Братство Кольца. Пейзажи Новой Зеландии, музыка Говарда Шора и бережная работа с книгой создают ощущение настоящего мира, в который быстро погружаешься.

Здесь меньше битв, чем в продолжениях, зато больше атмосферы. Отличное начало, после которого сразу тянет включить вторую часть.', 1, '2025-08-09 12:00:00'),
  (6, 'Властелин колец: Две крепости', 2002, 'lotr-towers.jpg', 'https://www.youtube.com/results?search_query=%D0%92%D0%BB%D0%B0%D1%81%D1%82%D0%B5%D0%BB%D0%B8%D0%BD%20%D0%BA%D0%BE%D0%BB%D0%B5%D1%86%3A%20%D0%94%D0%B2%D0%B5%20%D0%BA%D1%80%D0%B5%D0%BF%D0%BE%D1%81%D1%82%D0%B8%20%D1%82%D1%80%D0%B5%D0%B9%D0%BB%D0%B5%D1%80', 'Самая тёмная и напряжённая часть трилогии.

Братство разделено, и фильм следит сразу за несколькими линиями: путь Фродо и Сэма с Горлумом, дорога Арагорна, Леголаса и Гимли, битва за Хельмову Падь. Сражение у крепости остаётся одним из лучших в жанре.

Горлум в этой части особенно удался: ему сочувствуешь и одновременно опасаешься его. Середина трилогии, которая нисколько не проседает.', 1, '2025-08-10 12:00:00'),
  (7, 'Властелин колец: Возвращение короля', 2003, 'lotr-return.jpg', 'https://www.youtube.com/results?search_query=%D0%92%D0%BB%D0%B0%D1%81%D1%82%D0%B5%D0%BB%D0%B8%D0%BD%20%D0%BA%D0%BE%D0%BB%D0%B5%D1%86%3A%20%D0%92%D0%BE%D0%B7%D0%B2%D1%80%D0%B0%D1%89%D0%B5%D0%BD%D0%B8%D0%B5%20%D0%BA%D0%BE%D1%80%D0%BE%D0%BB%D1%8F%20%D1%82%D1%80%D0%B5%D0%B9%D0%BB%D0%B5%D1%80', 'Достойное завершение большой саги.

Последняя часть трилогии собирает всё, что было выстроено в первых двух: битву за Минас Тирит, путь Фродо и Сэма к Роковой горе и прощание героев. Масштаб огромный, но личные истории не теряются на фоне сражений.

Фильм получил одиннадцать «Оскаров», и это не удивляет. Финал длинный, но оставляет ощущение, что история действительно закончена.', 1, '2025-08-11 12:00:00'),
  (8, '1+1', 2011, 'intouchables.jpg', 'https://www.youtube.com/results?search_query=1%2B1%20%D1%82%D1%80%D0%B5%D0%B9%D0%BB%D0%B5%D1%80', 'Комедия, после которой остаётся тёплое чувство.

История дружбы аристократа, прикованного к инвалидному креслу, и его нового помощника из пригорода. Франсуа Клюзе и Омар Си играют так естественно, что за их общением наблюдаешь, как за настоящей дружбой.

Фильм смешной, но не пустой: в нём есть и грусть, и честный разговор о том, как люди относятся друг к другу. Его легко рекомендовать любому.', 1, '2025-08-12 12:00:00'),
  (9, 'Интерстеллар', 2014, 'interstellar.jpg', 'https://www.youtube.com/results?search_query=%D0%98%D0%BD%D1%82%D0%B5%D1%80%D1%81%D1%82%D0%B5%D0%BB%D0%BB%D0%B0%D1%80%20%D1%82%D1%80%D0%B5%D0%B9%D0%BB%D0%B5%D1%80', 'Фантастика, где главное это человеческие отношения.

Кристофер Нолан снимает большое космическое путешествие, но в центре остаётся история отца и дочери. Музыка Ханса Циммера и образ чёрной дыры создают ощущение, что смотришь что-то по-настоящему масштабное.

Фильм требует внимания: некоторые сцены трудно понять с первого раза. Зато после просмотра хочется обсуждать его и пересматривать.', 1, '2025-08-13 12:00:00'),
  (10, 'Тайна Коко', 2017, 'coco.jpg', 'https://www.youtube.com/results?search_query=%D0%A2%D0%B0%D0%B9%D0%BD%D0%B0%20%D0%9A%D0%BE%D0%BA%D0%BE%20%D1%82%D1%80%D0%B5%D0%B9%D0%BB%D0%B5%D1%80', 'Яркий мультфильм о памяти и семье.

Мальчик Мигель мечтает стать музыкантом, хотя в его семье музыка под запретом, и случайно попадает в Страну мёртвых. Картинка очень красивая, а музыка запоминается с первого раза.

Это добрая история о том, что нужно помнить близких, и о праве заниматься тем, что любишь. Подойдёт и детям, и взрослым.', 1, '2025-08-14 12:00:00');

INSERT INTO comments (review_id, user_id, text, created_at) VALUES
  (2, 2, 'Имя, не нуждающееся в представлении. Человек, выдумавший уйму увлекательных сюжетов, создавший прекрасные и загадочные миры, отличающиеся мрачностью и таинственностью.', '2025-08-10 10:00:00'),
  (2, 3, 'С экранизациями собственных романов Кингу всегда не везло. Большинство режиссёров предпочитало снимать, опираясь на своё видение сюжета, тогда как исключительная кинговская атмосфера пропадала.', '2025-08-11 11:00:00'),
  (2, 4, 'Либо режиссёр пытался наворотить кучу спецэффектов, и получалась ерунда («Ловец снов»), либо режиссёр всё переиначивал на свой лад, и творился ад кромешный в сценарном плане («Сияние» Кубрика, кстати говоря, та же беда', '2025-08-12 12:00:00'),
  (2, 2, 'Имя, не нуждающееся в представлении. Человек, выдумавший уйму увлекательных сюжетов, создавший прекрасные и загадочные миры, отличающиеся мрачностью и таинственностью.', '2025-08-13 13:00:00'),
  (1, 3, 'Лучший фильм, который я видел. Пересматриваю каждый год.', '2025-08-20 18:00:00'),
  (1, 4, 'Согласен, концовка пробирает до мурашек.', '2025-08-21 18:01:00'),
  (3, 3, 'Музыка и операторская работа просто невероятные.', '2025-08-20 18:00:00'),
  (9, 3, 'Нолан в очередной раз удивил, смотрел с замиранием сердца.', '2025-08-20 18:00:00');
